public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            i++;
            if (i < str.length()) {
                char nextChar = str.charAt(i);
                switch (nextChar) {
                    case 'b':
                        sb.append('\b');
                        break;
                    case 't':
                        sb.append('\t');
                        break;
                    case 'n':
                        sb.append('\n');
                        break;
                    case 'f':
                        sb.append('\f');
                        break;
                    case 'r':
                        sb.append('\r');
                        break;
                    case 'u':
                        if (i + 3 < str.length()) {
                            String hex = str.substring(i + 1, i + 5);
                            sb.append((char) Integer.parseInt(hex, 16));
                            i += 4;
                        } else {
                            throw new Exception("Invalid escape sequence: \\u");
                        }
                        break;
                    case '\\':
                        sb.append('\\');
                        break;
                    default:
                        sb.append(c);
                        sb.append(nextChar);
                        break;
                }
            } else {
                throw new Exception("Invalid escape sequence: \\");
            }
        } else {
            sb.append(c);
            i++;
        }
    }
    return sb.toString();
}

